## Universal Block Parser

### Cell Attribute Reading

xterm.js stores rich attributes per cell. The parser reads these to classify content without relying on text patterns.

```typescript
interface CellInfo {
  char: string;
  fg: number;          // Foreground color (0-255 palette index, or RGB)
  bg: number;          // Background color
  bold: boolean;
  dim: boolean;
  italic: boolean;
  underline: boolean;
  inverse: boolean;
}

interface LineInfo {
  row: number;
  text: string;                    // Full line text (trimmed trailing whitespace)
  cells: CellInfo[];               // Per-cell attributes
  indentLevel: number;             // Leading whitespace count
  dominantFg: number;              // Most common non-default foreground color
  dominantBg: number;              // Most common non-default background color
  hasBullet: boolean;              // Starts with ●, ◆, ▶, *, -, or similar
  bulletColor: number | null;      // Foreground color of the bullet character
  firstNonSpaceIsBold: boolean;    // First visible character is bold
  hasBackgroundHighlight: boolean; // Any cell has a non-default background
  isBlank: boolean;                // Line is empty or whitespace-only
  hasBoxDrawing: boolean;          // Contains └, ├, │, ─, etc.
}
```

### Line Analysis

```typescript
function analyzeLineFromBuffer(buffer: IBuffer, row: number, defaultFg: number, defaultBg: number): LineInfo {
  const line = buffer.getLine(row);
  if (!line) return BLANK_LINE;

  const cells: CellInfo[] = [];
  const colorCounts: Map<number, number> = new Map();
  let indent = 0;
  let countingIndent = true;
  let hasBullet = false;
  let bulletColor: number | null = null;
  let firstNonSpaceBold = false;
  let hasHighlight = false;
  let hasBoxDrawing = false;
  let firstNonSpace = true;

  const BULLET_CHARS = new Set(['●', '◆', '▶', '◇', '○', '•', '*', '■', '►']);
  const BOX_CHARS = new Set(['└', '├', '│', '─', '┌', '┐', '┘', '┤', '┬', '┴', '┼', '╭', '╮', '╰', '╯']);

  for (let col = 0; col < line.length; col++) {
    const cell = line.getCell(col);
    if (!cell) continue;

    const char = cell.getChars();
    const fg = cell.getFgColor();
    const bg = cell.getBgColor();
    const bold = cell.isBold() === 1;

    if (countingIndent && (char === ' ' || char === '')) {
      indent++;
      continue;
    }
    countingIndent = false;

    if (firstNonSpace) {
      firstNonSpace = false;
      firstNonSpaceBold = bold;
      if (BULLET_CHARS.has(char)) {
        hasBullet = true;
        bulletColor = fg;
      }
    }

    if (BOX_CHARS.has(char)) hasBoxDrawing = true;
    if (bg !== defaultBg) hasHighlight = true;
    if (fg !== defaultFg) colorCounts.set(fg, (colorCounts.get(fg) ?? 0) + 1);

    cells.push({ char, fg, bg, bold, dim: cell.isDim() === 1, italic: cell.isItalic() === 1, underline: cell.isUnderline() === 1, inverse: cell.isInverse() === 1 });
  }

  const text = line.translateToString(true);
  const dominantFg = colorCounts.size > 0
    ? [...colorCounts.entries()].sort((a, b) => b[1] - a[1])[0][0]
    : defaultFg;

  return {
    row, text, cells, indentLevel: indent, dominantFg, dominantBg: defaultBg,
    hasBullet, bulletColor, firstNonSpaceIsBold: firstNonSpaceBold,
    hasBackgroundHighlight: hasHighlight, isBlank: text.trim().length === 0,
    hasBoxDrawing,
  };
}
```

### Block Classification

Lines are grouped into blocks, then each block is classified.

```typescript
type BlockType =
  | "user-input"       // User's typed message/prompt
  | "agent-text"       // Agent's response text
  | "tool-call"        // Tool invocation header (e.g., Bash(...))
  | "tool-output"      // Tool execution output
  | "status-bar"       // Bottom status line
  | "separator"        // Blank lines between blocks
  | "plain";           // Unclassified content (fallback)

interface TerminalBlock {
  type: BlockType;
  lines: LineInfo[];
  confidence: number;  // 0.0 - 1.0, how confident we are in the classification
  collapsed: boolean;  // UI state: whether the block is collapsed
  color: string;       // CSS color derived from dominant terminal color
}
```

#### Grouping Algorithm

Lines are grouped by detecting **transitions** — points where the visual attributes change significantly.

```typescript
function detectBlockBoundary(prev: LineInfo, curr: LineInfo): boolean {
  // Blank line is always a boundary
  if (prev.isBlank || curr.isBlank) return true;

  // Bullet start is always a new block
  if (curr.hasBullet && curr.indentLevel === 0) return true;

  // Background highlight transition (entering/leaving user input)
  if (prev.hasBackgroundHighlight !== curr.hasBackgroundHighlight) return true;

  // Major indent level change (0 → 2+ or 2+ → 0)
  if (prev.indentLevel === 0 && curr.indentLevel >= 2) return true;
  if (prev.indentLevel >= 2 && curr.indentLevel === 0 && !curr.hasBoxDrawing) return true;

  // Dominant color change at indent 0 (different block type)
  if (prev.indentLevel === 0 && curr.indentLevel === 0 &&
      prev.dominantFg !== curr.dominantFg && curr.hasBullet) return true;

  return false;
}
```

#### Classification Algorithm

```typescript
function classifyBlock(block: LineInfo[]): { type: BlockType; confidence: number } {
  const first = block[0];
  const lineCount = block.length;

  // Status bar: last line(s) of terminal, typically has multiple color segments
  // Detected by position — always at the bottom of the viewport
  // Handled separately, not by this function.

  // User input: background highlight on the block
  if (first.hasBackgroundHighlight) {
    return { type: "user-input", confidence: 0.9 };
  }

  // Tool call: bullet + bold first word + contains parentheses
  if (first.hasBullet && first.firstNonSpaceIsBold) {
    const text = first.text.trim();
    // Check if it looks like ToolName(...) pattern
    const afterBullet = text.replace(/^[●◆▶◇○•*■►]\s*/, '');
    if (afterBullet.includes('(')) {
      return { type: "tool-call", confidence: 0.95 };
    }
    // Bullet + bold but no parens → agent message
    return { type: "agent-text", confidence: 0.85 };
  }

  // Tool output: indented content, possibly with box-drawing characters
  if (first.indentLevel >= 2 || first.hasBoxDrawing) {
    return { type: "tool-output", confidence: 0.8 };
  }

  // Agent text: bullet without bold (informational message)
  if (first.hasBullet) {
    return { type: "agent-text", confidence: 0.8 };
  }

  // Continuation text at indent 0 without bullet — likely agent text continuation
  if (first.indentLevel === 0 && !first.isBlank) {
    return { type: "agent-text", confidence: 0.5 };
  }

  // Blank lines
  if (block.every(l => l.isBlank)) {
    return { type: "separator", confidence: 1.0 };
  }

  return { type: "plain", confidence: 0.3 };
}
```

### Color Mapping

Terminal palette indices are mapped to CSS colors for the React renderer.

```typescript
// xterm 256-color palette index → CSS color
function paletteToCSS(index: number): string {
  // Standard ANSI colors (0-15)
  const ANSI_COLORS = [
    '#000000', '#cd0000', '#00cd00', '#cdcd00', '#0000ee', '#cd00cd', '#00cdcd', '#e5e5e5',
    '#7f7f7f', '#ff0000', '#00ff00', '#ffff00', '#5c5cff', '#ff00ff', '#00ffff', '#ffffff',
  ];
  if (index < 16) return ANSI_COLORS[index];

  // 216-color cube (16-231)
  if (index < 232) {
    const i = index - 16;
    const r = Math.floor(i / 36) * 51;
    const g = Math.floor((i % 36) / 6) * 51;
    const b = (i % 6) * 51;
    return `rgb(${r},${g},${b})`;
  }

  // Grayscale ramp (232-255)
  const gray = (index - 232) * 10 + 8;
  return `rgb(${gray},${gray},${gray})`;
}
```

